"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import {
  AlertTriangle,
  ArrowLeft,
  ArrowRight,
  Keyboard,
  Mic,
  Square,
  Timer,
} from "lucide-react";
import MicWave from "@/components/MicWave";
import { LANGUAGES } from "@/lib/content";
import { useSpeechRecognition } from "@/lib/useSpeechRecognition";
import { formatClock } from "@/lib/utils";
import type { Calibration } from "@/lib/types";

interface RecordStepProps {
  calibration: Calibration;
  onComplete: (transcript: string, elapsedSec: number) => void;
  onBack: () => void;
}

export default function RecordStep({ calibration, onComplete, onBack }: RecordStepProps) {
  const locale = LANGUAGES.find((item) => item.id === calibration.language)?.locale ?? "id-ID";
  const { supported, listening, finalText, interimText, error, start, stop, reset } =
    useSpeechRecognition(locale);

  const [manualMode, setManualMode] = useState(false);
  const [manualText, setManualText] = useState("");
  const [running, setRunning] = useState(false);
  const [elapsed, setElapsed] = useState(0);

  const elapsedRef = useRef(0);
  const textRef = useRef("");
  const finishedRef = useRef(false);
  const runningRef = useRef(false);

  useEffect(() => {
    if (!supported) setManualMode(true);
  }, [supported]);

  useEffect(() => {
    elapsedRef.current = elapsed;
  }, [elapsed]);

  useEffect(() => {
    textRef.current = manualMode
      ? manualText
      : `${finalText}${interimText ? ` ${interimText}` : ""}`.trim();
  }, [manualMode, manualText, finalText, interimText]);

  useEffect(() => {
    runningRef.current = running;
  }, [running]);

  const finish = useCallback(() => {
    if (finishedRef.current) return;
    finishedRef.current = true;
    stop();
    setRunning(false);
    const transcript = textRef.current.trim();
    const used = Math.max(1, Math.min(calibration.duration, elapsedRef.current || 1));
    onComplete(transcript, used);
  }, [calibration.duration, onComplete, stop]);

  useEffect(() => {
    if (!running) return;
    const interval = window.setInterval(() => {
      setElapsed((prev) => Math.min(calibration.duration, prev + 1));
    }, 1000);
    return () => window.clearInterval(interval);
  }, [running, calibration.duration]);

  useEffect(() => {
    if (running && elapsed >= calibration.duration) {
      finish();
    }
  }, [running, elapsed, calibration.duration, finish]);

  const handleStart = () => {
    reset();
    finishedRef.current = false;
    setElapsed(0);
    setRunning(true);
    if (!manualMode) start();
  };

  const handleStop = () => {
    finish();
  };

  const progress = Math.min(100, (elapsed / calibration.duration) * 100);
  const remaining = Math.max(0, calibration.duration - elapsed);
  const words = textRef.current ? textRef.current.split(/\s+/).length : 0;

  return (
    <div className="mx-auto w-full max-w-4xl">
      <div className="mb-6 flex flex-wrap items-end justify-between gap-3">
        <div>
          <p className="font-mono text-xs font-semibold uppercase tracking-widest text-gold">
            Step 2 · Delivery
          </p>
          <h1 className="mt-2 font-display text-3xl font-bold tracking-tight text-ink sm:text-4xl">
            Panggungnya udah siap. Bicara natural aja.
          </h1>
          <p className="mt-2 max-w-2xl text-sm leading-relaxed text-muted">
            {calibration.persona} bakal dengerin. Jangan baca teks — jelasin kayak lagi
            cerita ke temen.
          </p>
        </div>
        <button
          type="button"
          onClick={onBack}
          className="inline-flex items-center gap-1.5 rounded-full border border-line bg-surface px-3 py-1.5 text-xs font-semibold text-muted transition hover:text-ink"
        >
          <ArrowLeft className="h-3.5 w-3.5" /> Ubah setelan
        </button>
      </div>

      <div className="rounded-3xl border border-line bg-surface p-5 shadow-[0_12px_40px_rgba(24,24,27,0.05)] sm:p-6">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2">
            <span
              className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-semibold ${
                running
                  ? "bg-danger-soft text-danger"
                  : listening
                    ? "bg-forest-soft text-forest"
                    : "bg-ivory text-muted"
              }`}
            >
              <span
                className={`h-2 w-2 rounded-full ${
                  running ? "animate-pulse bg-danger" : "bg-muted/50"
                }`}
              />
              {running ? "REC" : "SIAP"}
            </span>
            <span className="font-mono text-[11px] uppercase tracking-wider text-muted">
              {calibration.duration / 60} menit · {calibration.language === "id" ? "ID" : "EN"}
            </span>
          </div>

          <button
            type="button"
            onClick={() => {
              if (running) handleStop();
              setManualMode((prev) => !prev);
            }}
            disabled={running}
            className="inline-flex items-center gap-1.5 rounded-full border border-line bg-ivory px-3 py-1.5 text-xs font-semibold text-muted transition hover:text-ink disabled:opacity-40"
          >
            <Keyboard className="h-3.5 w-3.5" />
            {manualMode ? "Pakai mic" : "Ketik manual"}
          </button>
        </div>

        <div className="mt-5 grid gap-5 sm:grid-cols-[1fr_auto] sm:items-center">
          <div>
            <div className="flex items-baseline gap-2">
              <span className="font-mono text-5xl font-bold tracking-tight text-ink sm:text-6xl">
                {formatClock(remaining)}
              </span>
              <span className="font-mono text-xs uppercase tracking-wider text-muted">
                sisa waktu
              </span>
            </div>
            <div className="mt-3 h-2 w-full overflow-hidden rounded-full bg-line">
              <motion.div
                className="h-full rounded-full bg-forest"
                animate={{ width: `${progress}%` }}
                transition={{ ease: "linear", duration: 0.4 }}
              />
            </div>
            <div className="mt-2 flex items-center justify-between font-mono text-[11px] text-muted">
              <span>{words} kata</span>
              <span className="inline-flex items-center gap-1">
                <Timer className="h-3 w-3" /> {formatClock(elapsed)} terpakai
              </span>
            </div>
          </div>

          <div className="flex flex-col gap-2">
            {!running ? (
              <button
                type="button"
                onClick={handleStart}
                className="inline-flex items-center justify-center gap-2 rounded-full bg-forest px-6 py-3.5 text-sm font-semibold text-white transition hover:bg-forest-hover"
              >
                <Mic className="h-4 w-4" /> Mulai rekam
              </button>
            ) : (
              <button
                type="button"
                onClick={handleStop}
                className="inline-flex items-center justify-center gap-2 rounded-full bg-danger px-6 py-3.5 text-sm font-semibold text-white transition hover:bg-danger/90"
              >
                <Square className="h-4 w-4" /> Stop & analisis
              </button>
            )}
            <p className="max-w-[190px] text-center text-[11px] leading-relaxed text-muted">
              Mic diproses di browser. Nggak ada rekaman audio yang dikirim ke server.
            </p>
          </div>
        </div>

        <div className="mt-4 rounded-2xl border border-line bg-ivory/70 px-3 py-2">
          <MicWave active={running && !manualMode} />
        </div>

        <AnimatePresence mode="wait">
          {manualMode ? (
            <motion.div
              key="manual"
              initial={{ opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -6 }}
              className="mt-4"
            >
              <label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-muted">
                Transkrip manual
              </label>
              <textarea
                value={manualText}
                onChange={(event) => setManualText(event.target.value)}
                rows={8}
                disabled={running}
                placeholder="Tempel atau ketik transkrip pitch kamu di sini. Minimal beberapa kalimat biar analisisnya berguna."
                className="w-full resize-y rounded-xl border border-line bg-surface px-4 py-3 text-sm leading-relaxed text-ink outline-none transition placeholder:text-muted/70 focus:border-forest disabled:opacity-70"
              />
              <div className="mt-2 flex items-center justify-between">
                <span className="font-mono text-[11px] text-muted">{manualText.trim().length} karakter</span>
                <button
                  type="button"
                  onClick={finish}
                  disabled={manualText.trim().length < 10}
                  className="inline-flex items-center gap-1.5 rounded-full bg-forest px-4 py-2 text-sm font-semibold text-white transition hover:bg-forest-hover disabled:opacity-40"
                >
                  Analisis transkrip <ArrowRight className="h-4 w-4" />
                </button>
              </div>
            </motion.div>
          ) : (
            <motion.div
              key="live"
              initial={{ opacity: 0, y: 6 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -6 }}
              className="mt-4"
            >
              <div className="mb-1.5 flex items-center justify-between">
                <span className="text-xs font-semibold uppercase tracking-wide text-muted">
                  Transkrip live
                </span>
                {listening ? (
                  <span className="inline-flex items-center gap-1 text-[11px] font-semibold text-forest">
                    <Mic className="h-3 w-3" /> dengerin...
                  </span>
                ) : null}
              </div>
              <div className="scrollbar-hide h-40 overflow-y-auto rounded-xl border border-line bg-ivory px-4 py-3 text-sm leading-relaxed text-ink">
                {finalText || interimText ? (
                  <p>
                    {finalText}{" "}
                    <span className="text-muted/80 italic">{interimText}</span>
                  </p>
                ) : (
                  <p className="text-muted">
                    Transkrip bakal muncul di sini begitu kamu mulai bicara...
                  </p>
                )}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {error ? (
          <div className="mt-3 flex items-start gap-2 rounded-xl bg-gold-soft px-3 py-2.5 text-xs leading-relaxed text-gold">
            <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
            <span>{error}</span>
          </div>
        ) : null}

        {!supported && !manualMode ? (
          <div className="mt-3 flex items-start gap-2 rounded-xl bg-gold-soft px-3 py-2.5 text-xs leading-relaxed text-gold">
            <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
            <span>
              Browser ini belum support Web Speech API. Mode ketik manual otomatis aktif.
            </span>
          </div>
        ) : null}
      </div>

      <div className="mt-5 grid gap-3 sm:grid-cols-3">
        {[
          "Buka dengan hook 15 detik: masalah + kenapa sekarang.",
          "Sebut satu angka konkret, jangan cuma “banyak”.",
          "Tutup dengan ask yang jelas: funding, validasi, atau keputusan.",
        ].map((tip) => (
          <div key={tip} className="rounded-xl border border-line bg-surface/60 px-3.5 py-3 text-xs leading-relaxed text-muted">
            {tip}
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { motion } from "motion/react";
import {
  ArrowRight,
  BarChart3,
  CheckCircle2,
  Loader2,
  Lock,
  Mic,
  RotateCcw,
  UserPlus,
} from "lucide-react";
import CalibrationStep from "./CalibrationStep";
import RecordStep from "./RecordStep";
import AuditStep from "./AuditStep";
import QAStep from "./QAStep";
import ScoreRing from "@/components/ScoreRing";
import { useAuth } from "@/components/AuthProvider";
import { analyzeFallback, generateQuestionsFallback } from "@/lib/analyzer";
import { planLabel } from "@/lib/plans";
import { canStartSession, getAccount, saveSession } from "@/lib/store";
import type {
  AuditResult,
  Calibration,
  QAEvaluation,
  QAQuestion,
  SessionReport,
} from "@/lib/types";

type Phase = "calibrate" | "record" | "analyzing" | "audit" | "questions" | "qa" | "done";

const LOADING_LINES = [
  "Ngebaca ulang pitch kamu...",
  "Ngitung tempo & filler words...",
  "Ngecek alur Problem → Solution → Business Model...",
  "Nyiapin catatan yang jujur tapi suportif...",
];

export default function StudioClient() {
  const { account, isLoggedIn, openAuth } = useAuth();
  const [phase, setPhase] = useState<Phase>("calibrate");
  const [calibration, setCalibration] = useState<Calibration | null>(null);
  const [transcript, setTranscript] = useState("");
  const [elapsed, setElapsed] = useState(0);
  const [audit, setAudit] = useState<AuditResult | null>(null);
  const [questions, setQuestions] = useState<QAQuestion[]>([]);
  const [evaluations, setEvaluations] = useState<QAEvaluation[]>([]);
  const [savedSession, setSavedSession] = useState<SessionReport | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const [limitInfo, setLimitInfo] = useState({
    blocked: false,
    plan: "free" as "free" | "pro" | "team",
    used: 0,
    limit: 2,
  });

  useEffect(() => {
    const info = canStartSession();
    setLimitInfo({
      blocked: !info.allowed,
      plan: info.plan,
      used: info.used,
      limit: info.limit === Number.POSITIVE_INFINITY ? 999 : info.limit,
    });
  }, []);

  const runAudit = useCallback(async (text: string, durationSec: number, config: Calibration) => {
    setPhase("analyzing");
    setErrorMessage(null);
    try {
      const response = await fetch("/api/analyze-pitch", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          mode: "audit",
          transcript: text,
          language: config.language,
          sessionType: config.sessionType,
          persona: config.persona,
          durationSec,
          pitchNotes: config.pitchNotes,
        }),
      });
      const data = (await response.json()) as { ok: boolean; audit?: AuditResult; error?: string };
      if (!data.ok || !data.audit) throw new Error(data.error || "Analisis gagal.");
      setAudit(data.audit);
      setPhase("audit");
    } catch {
      setAudit(
        analyzeFallback({
          transcript: text,
          language: config.language,
          durationSec,
          sessionType: config.sessionType,
        }),
      );
      setErrorMessage("Koneksi ke AI lagi rewel, jadi kami pakai analyzer lokal dulu.");
      setPhase("audit");
    }
  }, []);

  const handleStart = (config: Calibration) => {
    setCalibration(config);
    setAudit(null);
    setQuestions([]);
    setEvaluations([]);
    setSavedSession(null);
    setTranscript("");
    setPhase("record");
  };

  const handleRecordComplete = (text: string, durationSec: number) => {
    if (!calibration) return;
    setTranscript(text);
    setElapsed(durationSec);
    void runAudit(text, durationSec, calibration);
  };

  const handleAuditNext = async () => {
    if (!calibration || !audit) return;
    setPhase("questions");
    setErrorMessage(null);
    try {
      const response = await fetch("/api/analyze-pitch", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          mode: "questions",
          transcript,
          language: calibration.language,
          sessionType: calibration.sessionType,
          persona: calibration.persona,
        }),
      });
      const data = (await response.json()) as { ok: boolean; questions?: QAQuestion[] };
      if (!data.ok || !data.questions || data.questions.length === 0) {
        throw new Error("Pertanyaan gagal dibuat.");
      }
      setQuestions(data.questions.slice(0, 3));
      setPhase("qa");
    } catch {
      setQuestions(
        generateQuestionsFallback({
          transcript,
          language: calibration.language,
          sessionType: calibration.sessionType,
          persona: calibration.persona,
        }).slice(0, 3),
      );
      setErrorMessage("Koneksi ke AI lagi rewel, pertanyaan dibuat pakai mode lokal.");
      setPhase("qa");
    }
  };

  const handleQAFinish = (results: QAEvaluation[]) => {
    if (!calibration || !audit) return;
    const qaAverage =
      results.length > 0 ? results.reduce((sum, item) => sum + item.score, 0) / results.length : 0;
    const overallScore =
      Math.round((audit.readinessScore * 0.7 + qaAverage * 0.3) * 10) / 10;
    const currentAccount = getAccount();
    const session: SessionReport = {
      id: crypto.randomUUID(),
      createdAt: Date.now(),
      mode: currentAccount ? "account" : "guest",
      ownerId: currentAccount?.id ?? "guest",
      calibration,
      transcript,
      audit,
      questions,
      qaResults: results,
      overallScore,
    };
    saveSession(session);
    setEvaluations(results);
    setSavedSession(session);
    setPhase("done");
  };

  const resetAll = () => {
    setPhase("calibrate");
    setCalibration(null);
    setTranscript("");
    setAudit(null);
    setQuestions([]);
    setEvaluations([]);
    setSavedSession(null);
    setErrorMessage(null);
  };

  if (phase === "calibrate") {
    return (
      <div className="px-4 py-10 sm:px-6 lg:py-14">
        <CalibrationStep
          onStart={handleStart}
          blocked={limitInfo.blocked}
          planLabelText={planLabel(limitInfo.plan)}
          used={limitInfo.used}
          limit={limitInfo.limit}
        />
      </div>
    );
  }

  if (phase === "record" && calibration) {
    return (
      <div className="px-4 py-10 sm:px-6 lg:py-14">
        <RecordStep
          calibration={calibration}
          onComplete={handleRecordComplete}
          onBack={() => setPhase("calibrate")}
        />
      </div>
    );
  }

  if (phase === "analyzing") {
    return (
      <div className="flex min-h-[70vh] items-center justify-center px-4">
        <div className="w-full max-w-sm text-center">
          <motion.div
            animate={{ rotate: 360 }}
            transition={{ repeat: Number.POSITIVE_INFINITY, duration: 1.6, ease: "linear" }}
            className="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-forest text-white"
          >
            <Loader2 className="h-6 w-6" />
          </motion.div>
          <h2 className="mt-5 font-display text-xl font-bold text-ink">Lagi dengerin ulang...</h2>
          <p className="mt-1 text-sm text-muted">Bentar ya, coach lagi nyatet.</p>
          <div className="mt-5 space-y-2 text-left">
            {LOADING_LINES.map((line, index) => (
              <motion.p
                key={line}
                initial={{ opacity: 0.25 }}
                animate={{ opacity: [0.25, 1, 0.25] }}
                transition={{ repeat: Number.POSITIVE_INFINITY, duration: 3.2, delay: index * 0.8 }}
                className="flex items-center gap-2 text-xs text-muted"
              >
                <span className="h-1 w-1 rounded-full bg-gold" /> {line}
              </motion.p>
            ))}
          </div>
        </div>
      </div>
    );
  }

  if (phase === "audit" && audit) {
    return (
      <div className="px-4 py-10 sm:px-6 lg:py-14">
        {errorMessage ? (
          <div className="mx-auto mb-4 w-full max-w-5xl rounded-xl bg-gold-soft px-4 py-2.5 text-xs text-gold">
            {errorMessage}
          </div>
        ) : null}
        <AuditStep
          audit={audit}
          transcript={transcript}
          onNext={handleAuditNext}
          onBack={() => setPhase("record")}
        />
      </div>
    );
  }

  if (phase === "questions") {
    return (
      <div className="flex min-h-[60vh] items-center justify-center px-4">
        <div className="text-center">
          <Loader2 className="mx-auto h-7 w-7 animate-spin text-forest" />
          <p className="mt-3 text-sm font-medium text-ink">Juri lagi nyusun pertanyaan...</p>
          <p className="mt-1 text-xs text-muted">Nyari bagian paling goyang dari pitch kamu.</p>
        </div>
      </div>
    );
  }

  if (phase === "qa" && calibration && questions.length > 0) {
    return (
      <div className="px-4 py-10 sm:px-6 lg:py-14">
        <QAStep
          questions={questions}
          language={calibration.language}
          sessionType={calibration.sessionType}
          persona={calibration.persona}
          onFinish={handleQAFinish}
          onBack={() => setPhase("audit")}
        />
      </div>
    );
  }

  if (phase === "done" && savedSession) {
    const qaAverage =
      evaluations.length > 0
        ? evaluations.reduce((sum, item) => sum + item.score, 0) / evaluations.length
        : 0;
    return (
      <div className="px-4 py-10 sm:px-6 lg:py-14">
        <div className="mx-auto w-full max-w-3xl text-center">
          <span className="inline-flex items-center gap-1.5 rounded-full bg-forest-soft px-3 py-1 text-xs font-semibold text-forest">
            <CheckCircle2 className="h-3.5 w-3.5" /> Sesi tersimpan
          </span>
          <h1 className="mt-4 font-display text-3xl font-bold tracking-tight text-ink sm:text-4xl">
            Kelar! Kamu baru aja naik satu level.
          </h1>
          <p className="mx-auto mt-2 max-w-xl text-sm leading-relaxed text-muted">
            Latihan kayak gini yang bikin pas hari-H kamu nggak kaget. Ulang 2–3 kali lagi
            dengan persona berbeda, hasilnya bakal kerasa banget.
          </p>

          <div className="mt-8 rounded-3xl border border-line bg-surface p-6 shadow-[0_16px_50px_rgba(24,24,27,0.06)]">
            <div className="flex flex-wrap items-center justify-center gap-8">
              <ScoreRing score={savedSession.overallScore} size={150} stroke={11} label="Overall" sublabel="readiness + Q&A" />
              <div className="grid grid-cols-2 gap-3">
                <div className="rounded-xl bg-ivory px-4 py-3">
                  <p className="font-mono text-2xl font-bold text-ink">
                    {savedSession.audit.deliveryScore.toFixed(1)}
                  </p>
                  <p className="text-[10px] uppercase tracking-wide text-muted">Delivery</p>
                </div>
                <div className="rounded-xl bg-ivory px-4 py-3">
                  <p className="font-mono text-2xl font-bold text-ink">{qaAverage.toFixed(1)}</p>
                  <p className="text-[10px] uppercase tracking-wide text-muted">Q&A</p>
                </div>
                <div className="rounded-xl bg-ivory px-4 py-3">
                  <p className="font-mono text-2xl font-bold text-ink">{savedSession.audit.wpm}</p>
                  <p className="text-[10px] uppercase tracking-wide text-muted">WPM</p>
                </div>
                <div className="rounded-xl bg-ivory px-4 py-3">
                  <p className="font-mono text-2xl font-bold text-ink">{savedSession.audit.fillerCount}</p>
                  <p className="text-[10px] uppercase tracking-wide text-muted">Filler</p>
                </div>
              </div>
            </div>

            {!isLoggedIn ? (
              <div className="mt-6 flex flex-col items-start gap-3 rounded-2xl border border-gold/25 bg-gold-soft p-4 text-left sm:flex-row sm:items-center sm:justify-between">
                <div className="flex items-start gap-2.5">
                  <Lock className="mt-0.5 h-4 w-4 shrink-0 text-gold" />
                  <div>
                    <p className="text-sm font-semibold text-ink">Sesi ini masih mode guest.</p>
                    <p className="text-xs leading-relaxed text-muted">
                      Bikin akun biar progres kamu nggak ilang kalau cache browser dibersihin.
                    </p>
                  </div>
                </div>
                <button
                  type="button"
                  onClick={() => openAuth("register")}
                  className="inline-flex shrink-0 items-center gap-1.5 rounded-full bg-forest px-4 py-2 text-xs font-semibold text-white transition hover:bg-forest-hover"
                >
                  <UserPlus className="h-3.5 w-3.5" /> Simpan akun permanen
                </button>
              </div>
            ) : (
              <p className="mt-5 text-xs text-muted">
                Tersimpan di akun <span className="font-semibold text-ink">{account?.name}</span>.
              </p>
            )}
          </div>

          <div className="mt-6 flex flex-col items-center justify-center gap-2 sm:flex-row">
            <Link
              href="/history"
              className="inline-flex w-full items-center justify-center gap-2 rounded-full bg-forest px-5 py-3 text-sm font-semibold text-white transition hover:bg-forest-hover sm:w-auto"
            >
              <BarChart3 className="h-4 w-4" /> Lihat laporan lengkap
            </Link>
            <button
              type="button"
              onClick={resetAll}
              className="inline-flex w-full items-center justify-center gap-2 rounded-full border border-line bg-surface px-5 py-3 text-sm font-semibold text-ink transition hover:border-forest/30 hover:text-forest sm:w-auto"
            >
              <RotateCcw className="h-4 w-4" /> Latihan lagi
            </button>
          </div>

          <Link
            href="/pricing"
            className="mt-4 inline-flex items-center gap-1 text-xs font-semibold text-muted transition hover:text-forest"
          >
            Mau sesi lebih panjang? Cek Pro Solo <ArrowRight className="h-3 w-3" />
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="px-4 py-16">
      <div className="mx-auto max-w-md rounded-2xl border border-line bg-surface p-6 text-center">
        <Mic className="mx-auto h-6 w-6 text-muted" />
        <p className="mt-3 text-sm font-semibold text-ink">Sesi belum siap.</p>
        <p className="mt-1 text-xs text-muted">Coba mulai ulang dari kalibrasi.</p>
        <button
          type="button"
          onClick={resetAll}
          className="mt-4 rounded-full bg-forest px-4 py-2 text-sm font-semibold text-white"
        >
          Mulai ulang
        </button>
      </div>
    </div>
  );
}

